import { t as supabase } from "./client-DtR6f4Ax.js";
import { useQuery } from "@tanstack/react-query";
//#region src/lib/finance.ts
function useProfile() {
	return useQuery({
		queryKey: ["profile"],
		queryFn: async () => {
			const { data: u } = await supabase.auth.getUser();
			if (!u.user) return null;
			const { data } = await supabase.from("profiles").select("*").eq("id", u.user.id).maybeSingle();
			return data ?? {
				id: u.user.id,
				name: u.user.email?.split("@")[0] ?? "",
				email: u.user.email ?? "",
				avatar_url: null
			};
		}
	});
}
function useTransactions() {
	return useQuery({
		queryKey: ["transactions"],
		queryFn: async () => {
			const { data, error } = await supabase.from("transactions").select("*").order("occurred_on", { ascending: false }).limit(500);
			if (error) throw error;
			return data ?? [];
		}
	});
}
function formatCurrency(n) {
	return new Intl.NumberFormat("en-US", {
		style: "currency",
		currency: "USD",
		maximumFractionDigits: 0
	}).format(n);
}
//#endregion
export { useProfile as n, useTransactions as r, formatCurrency as t };
